package com.bank.gateway.ratelimit;

import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;

// Token bucket: refill at a steady rate, allow bursts up to capacity.
public class TokenBucketRateLimiter implements RateLimiter {
    private final double refillPerSecond;
    private final double capacity;
    // Per-client state would live in Redis in production (shared across instances).
    private final Map<String, double[]> buckets = new ConcurrentHashMap<>(); // [tokens, lastRefillNanos]

    public TokenBucketRateLimiter(double refillPerSecond, double capacity) {
        this.refillPerSecond = refillPerSecond;
        this.capacity = capacity;
    }

    @Override public synchronized boolean allow(String clientId) {
        double[] state = buckets.computeIfAbsent(clientId,
                k -> new double[]{capacity, System.nanoTime()});
        long now = System.nanoTime();
        double elapsedSec = (now - state[1]) / 1_000_000_000.0;
        state[0] = Math.min(capacity, state[0] + elapsedSec * refillPerSecond); // refill
        state[1] = now;
            if (state[0] >= 1.0) { state[0] -= 1.0;
            return true; }  // consume a token
        return false;                                            // no token -> 429
    }
    @Override public String algorithm() { return "token-bucket"; }
}
