package com.bank.gateway.ratelimit;

import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;

// Fixed-window counter: simple, but allows ~2x burst at the window boundary.
public class FixedWindowRateLimiter implements RateLimiter {
    private final int limit;
    private final long windowMillis;
    private final Map<String, long[]> windows = new ConcurrentHashMap<>(); // [windowStart, count]

    public FixedWindowRateLimiter(int limit, long windowMillis) {
            this.limit = limit;
            this.windowMillis = windowMillis;
    }

    @Override public synchronized boolean allow(String clientId) {
        long now = System.currentTimeMillis();
        long[] w = windows.computeIfAbsent(clientId, k -> new long[]{now, 0});
        if (now - w[0] >= windowMillis) { w[0] = now; w[1] = 0; } // new window resets count
        if (w[1] < limit) { w[1]++; return true; }
        return false;
    }
    @Override public String algorithm() { return "fixed-window"; }
}
