package com.bank.gateway.pipeline;

import com.bank.gateway.balancer.LeastConnectionsBalancer;
import com.bank.gateway.balancer.ServiceInstance;
import com.bank.gateway.ratelimit.RateLimiter;
import java.util.List;
import java.util.logging.Logger;

// Edge path: RATE LIMIT first (admission), then LOAD BALANCE (placement).
public class GatewayPipeline {
    private static final Logger log = Logger.getLogger(GatewayPipeline.class.getName());
    private final RateLimiter rateLimiter;
    private final LeastConnectionsBalancer balancer;
    private final List<ServiceInstance> instances;
    private int accepted = 0, rejected = 0;

    public GatewayPipeline(RateLimiter rateLimiter, LeastConnectionsBalancer balancer,
                           List<ServiceInstance> instances) {
        this.rateLimiter = rateLimiter;
        this.balancer = balancer;
        this.instances = instances;
    }

    // Returns the instance id that served it, or "429" if rate-limited.
    public String handle(String clientId) {
        if (!rateLimiter.allow(clientId)) {
            rejected++;
            log.warning(() -> "429 Too Many Requests for client " + clientId
                    + " (" + rateLimiter.algorithm() + ")");
            return "429";
        }
        ServiceInstance target = balancer.choose(instances);
        target.acquire();
        accepted++;
        log.fine(() -> "ADMIT " + clientId + " -> " + target.getId()
                + " (active=" + target.getActive() + ")");
        target.release(); // simulate quick completion
        return target.getId();
    }

    public int getAccepted() { return accepted; }
    public int getRejected() { return rejected; }
}
