package com.bank.gateway;

import com.bank.gateway.balancer.LeastConnectionsBalancer;
import com.bank.gateway.balancer.ServiceInstance;
import com.bank.gateway.pipeline.GatewayPipeline;
import com.bank.gateway.ratelimit.TokenBucketRateLimiter;
import java.util.*;
import java.util.logging.*;

public class GatewayDemo {
    public static void main(String[] args) {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) h.setFormatter(new BankLogFormatter());
        Logger log = Logger.getLogger(GatewayDemo.class.getName());

        List<ServiceInstance> instances = List.of(
                new ServiceInstance("txn-1"),
                new ServiceInstance("txn-2"),
                new ServiceInstance("txn-3"));
        LeastConnectionsBalancer balancer = new LeastConnectionsBalancer();

        // Token bucket: refill 10/sec, burst capacity 20.
        TokenBucketRateLimiter limiter = new TokenBucketRateLimiter(10, 20);
        GatewayPipeline gateway = new GatewayPipeline(limiter, balancer, instances);

        // NORMAL client: a few requests, all admitted and spread across instances.
        log.info("=== Normal client (within limit) ===");
        Map<String,Integer> spread = new TreeMap<>();
        for (int i = 0; i < 6; i++) {
            String served = gateway.handle("rajesh-SAV2001");
            spread.merge(served, 1, Integer::sum);
        }
        log.info("normal client spread across instances: " + spread);

        // ABUSIVE client: 50 rapid requests, bucket (20) drains then 429s.
        log.severe("=== Abusive client (buggy retry loop) ===");
        int ok = 0, blocked = 0;
        for (int i = 0; i < 50; i++) {
            if (gateway.handle("buggy-client-X").equals("429")) blocked++; else ok++;
        }
        log.info("abusive client: admitted=" + ok + " (burst up to 20), blocked(429)=" + blocked);
        log.info("Gateway totals: accepted=" + gateway.getAccepted()
                + ", rejected=" + gateway.getRejected()
                + " (real customers protected)");
    }
}

